"""Regenerate reference/effects.md from fx_catalog.py (run after adding or changing presets)."""
import os
import fx_catalog as C

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def fmt(d):
    return ", ".join(f"{k} {v}" for k, v in d.items() if k != "type")


lines = ["# Effect catalog", "",
         "Generated by `scripts/fx_docs.py` from `scripts/fx_catalog.py`. Demo clip per preset: `gallery/fx/<name>.mp4` (render them with `fx_gallery.py`).", "",
         "How the user asks: \"pasang shake_3 + flash_2 di kill 5\", \"transisi whip_1 setelah kill 8\", \"speed hero di kill 1\".",
         "In edl.json: `\"effects\": [{\"preset\": \"shake_3\"}, {\"preset\": \"flash_2\"}]`, `\"transition_out\": {\"preset\": \"whip_1\"}`,",
         "`\"speed\": {\"preset\": \"hero\"}`, texts `{\"preset\": \"word_pop\", \"text\": \"BANG\", \"beat\": 24, \"dur\": 2}`.",
         "Effect strength is multiplied by the clip's `intensity`.", "",
         "## Kill effects (start on the kill frame)", "", "| Preset | Type | Looks like | Settings |", "|---|---|---|---|"]
lines += [f"| `{n}` | {p['type']} | {C.EFFECT_INFO.get(n, '')} | {fmt(p)} |" for n, p in C.EFFECTS.items()]
lines += ["", "## Transitions (on the cut after a clip)", "", "| Preset | Type | Looks like | Duration (s) |", "|---|---|---|---|"]
lines += [f"| `{n}` | {p['type']} | {C.TRANSITION_INFO.get(n, '')} | {p['dur']} |" for n, p in C.TRANSITIONS.items()]
lines += ["", "## Speed styles (pre = start of clip to the kill, post = kill to end; pairs are (fraction, speed))", "",
          "| Preset | Feels like | Pre | Post |", "|---|---|---|---|"]
lines += [f"| `{n}` | {C.SPEED_INFO.get(n, '')} | {p['pre']} | {p['post']} |" for n, p in C.SPEED.items()]
lines += ["", "## Text styles", "", "| Preset | Looks like | Settings |", "|---|---|---|"]
lines += [f"| `{n}` | {C.TEXT_INFO.get(n, '')} | {fmt(p)} |" for n, p in C.TEXTS.items()]
lines += ["", "## Adding a new look", "",
          "1. Add a preset to `fx_catalog.py` (+ a line in the matching `*_INFO`). A brand-new effect type also needs a branch in `render.py` (`kill_effects` sets a state value, `clip_frame` draws it).",
          "2. From `gallery/`: `py -3.14 ../scripts/fx_gallery.py --video <recording> --kill 79742 --kill2 98896 --out . --only <name>`.",
          "3. Run `fx_docs.py`, add the clip to the catalog page and republish it.", ""]
open(os.path.join(ROOT, "reference", "effects.md"), "w", encoding="utf-8").write("\n".join(lines))
print("reference/effects.md written:", len(C.EFFECTS), "effects,", len(C.TRANSITIONS), "transitions,", len(C.SPEED), "speeds,", len(C.TEXTS), "texts")
